param(
    [Alias("TargetRoot")]
    [string]$ProjectPath = ".",
    [switch]$Force,
    [switch]$InitGit,
    [switch]$InitOpenSpec
)

$ErrorActionPreference = "Stop"

try {
    [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
} catch {
    # Older PowerShell hosts may not allow changing output encoding. Ignore safely.
}

function Write-Info { param([string]$Message) Write-Host "[info] $Message" }
function Write-Ok { param([string]$Message) Write-Host "[ok] $Message" }
function Write-Warn { param([string]$Message) Write-Host "[warn] $Message" }

function Test-CommandExists {
    param([string]$Command)
    return $null -ne (Get-Command $Command -ErrorAction SilentlyContinue)
}

function Invoke-OpenSpec {
    param([string[]]$Arguments)

    if (Test-CommandExists "openspec") {
        & openspec @Arguments
        return
    }

    if (Test-CommandExists "npx") {
        & npx --yes "@fission-ai/openspec@1.4.1" @Arguments
        return
    }

    throw "Neither 'openspec' nor 'npx' is available. Install OpenSpec or Node.js/npm first."
}

function Write-EmbeddedAsset {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][byte[]]$Bytes,
        [Parameter(Mandatory = $true)][string]$TargetRoot
    )

    if ([System.IO.Path]::IsPathRooted($RelativePath) -or $RelativePath -match '(^|/)\.\.(/|$)') {
        throw "Unsafe embedded asset path: $RelativePath"
    }

    $destination = Join-Path $TargetRoot ($RelativePath -replace '/', [System.IO.Path]::DirectorySeparatorChar)

    if ((Test-Path -LiteralPath $destination) -and (-not $Force)) {
        Write-Host "[skip] $destination already exists"
        return
    }

    $parent = Split-Path -Parent $destination
    if ($parent -and !(Test-Path -LiteralPath $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }

    [System.IO.File]::WriteAllBytes($destination, $Bytes)
    Write-Host "[write] $destination"
}

function Expand-EmbeddedAssets {
    param([Parameter(Mandatory = $true)][string]$TargetRoot)

    Add-Type -AssemblyName System.IO.Compression | Out-Null

    $zipBase64 = @'

'@

    $zipBytes = [Convert]::FromBase64String(($zipBase64 -replace '\s', ''))
    $stream = New-Object System.IO.MemoryStream(,$zipBytes)

    try {
        $archive = New-Object System.IO.Compression.ZipArchive($stream, [System.IO.Compression.ZipArchiveMode]::Read, $false)
        try {
            foreach ($entry in $archive.Entries) {
                if ([string]::IsNullOrWhiteSpace($entry.FullName) -or $entry.FullName.EndsWith('/')) {
                    continue
                }

                $entryStream = $entry.Open()
                try {
                    $assetStream = New-Object System.IO.MemoryStream
                    try {
                        $entryStream.CopyTo($assetStream)
                        Write-EmbeddedAsset -RelativePath $entry.FullName -Bytes $assetStream.ToArray() -TargetRoot $TargetRoot
                    } finally {
                        $assetStream.Dispose()
                    }
                } finally {
                    $entryStream.Dispose()
                }
            }
        } finally {
            $archive.Dispose()
        }
    } finally {
        $stream.Dispose()
    }
}

$targetPath = $ProjectPath
if (!(Test-Path -LiteralPath $targetPath)) {
    New-Item -ItemType Directory -Force -Path $targetPath | Out-Null
}

$targetRoot = (Resolve-Path $targetPath).Path

Write-Info "Bootstrapping AI Dev SOP in $targetRoot"
Write-Info "Using embedded SOP assets from this script"

Push-Location $targetRoot
try {
    if (-not $InitGit) {
        Write-Warn "InitGit is not enabled. Skipping git init."
    } elseif (Test-Path ".git") {
        Write-Ok ".git already exists"
    } elseif (Test-CommandExists "git") {
        Write-Info ".git not found. Running git init..."
        git init
        Write-Ok "git init completed"
    } else {
        Write-Warn "git command not found. Please install Git or run git init manually."
    }

    if (-not $InitOpenSpec) {
        Write-Warn "InitOpenSpec is not enabled. Skipping openspec init."
    } elseif (Test-Path "openspec") {
        Write-Ok "openspec folder already exists"
    } else {
        Write-Info "openspec folder not found. Running openspec init..."
        Write-Warn "If OpenSpec asks you to select tools, choose Codex or press Enter according to the prompt."
        Invoke-OpenSpec @("init")
        Write-Ok "openspec init completed or handed off to interactive setup"
    }
} finally {
    Pop-Location
}

Expand-EmbeddedAssets -TargetRoot $targetRoot

Write-Ok "AI Dev SOP bootstrap complete"
Write-Host ""
Write-Host "Next steps:"
Write-Host "1. Put long requirements in a UTF-8 file such as requirement.md."
Write-Host '2. Read docs\ai-sop-usage.md, then create current prompts with scripts\new-ai-change-prompt.ps1.'
Write-Host "3. Start Codex in the target project."
Write-Host "4. Ask Codex to read docs\prompts\current-00-router.md and execute it."

